<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import HeroProfile from './HeroProfile.vue'
import HeroAtmosphere from './HeroAtmosphere.vue'
import archivePreviews from './archive-previews.json'
import {profile,games,creativeWorks,creatureWorks} from './content.js'
const props=defineProps({embedded:Boolean})
const emit=defineEmits(['done','select-work'])
const phase=ref('closed')
function finish(){phase.value='home';emit('done')}
const projects=[...creativeWorks.map(p=>({...p,href:'/#creative'})),...games.filter(p=>p.cover).map(p=>({...p,href:`/#game-${games.indexOf(p)}`})),...creatureWorks.map(p=>({...p,href:'/#creative'}))]
const cards=[],galleries=projects.map(p=>(p.images||p.gallery||[{src:p.cover}]).map(image=>({title:p.title,src:image.src,href:p.href})))
for(let row=0;row<Math.max(...galleries.map(g=>g.length));row++)galleries.forEach(g=>{if(g[row])cards.push(g[row])})
const deck=projects.map(p=>({title:p.title,src:archivePreviews[(p.images||p.gallery||[{src:p.cover}])[0].src]||(p.images||p.gallery||[{src:p.cover}])[0].src,href:p.href}))
const archiveTurn=ref(0),archiveDrag=ref(null)
const visibleDeck=computed(()=>{const n=deck.length,k=(archiveTurn.value%n+n)%n;return [...deck.slice(k),...deck.slice(0,k)]})
function startArchiveDrag(event){if(phase.value!=='home'||event.button!==0)return;archiveDrag.value={x:event.clientX,id:event.pointerId};event.currentTarget.setPointerCapture(event.pointerId)}
function endArchiveDrag(event){if(!archiveDrag.value)return;const delta=event.clientX-archiveDrag.value.x;archiveDrag.value=null;if(Math.abs(delta)>35)archiveTurn.value+=delta>0?1:-1}
let raf,started=0,disposed=false,userSkipped=false
function run(now){
 if(!started)started=now
 const t=now-started
 if(t<300)phase.value='closed'
 else if(t<1430)phase.value='catching'
 else {finish();return}
 raf=requestAnimationFrame(run)
}
function replay(){cancelAnimationFrame(raf);phase.value='closed';started=0;raf=requestAnimationFrame(run)}
function skip(){userSkipped=true;cancelAnimationFrame(raf);finish()}
onMounted(async()=>{
 await Promise.all(deck.map(card=>new Promise(resolve=>{const img=new Image();img.onload=()=>{img.decode().catch(()=>{}).then(resolve)};img.onerror=resolve;img.src=card.src})))
 if(disposed||userSkipped)return
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)skip();else {
  if(props.embedded)window.scrollTo({top:0,left:0,behavior:'instant'})
  replay()
 }
})
onBeforeUnmount(()=>{disposed=true;cancelAnimationFrame(raf)})
</script>
<template>
 <section class="folder-demo" :class="[phase,{embedded}]" aria-label="创作档案首页">
  <HeroAtmosphere :animated="phase==='home'"/>
  <header v-if="!embedded"><a href="/">BUILD <span>✳</span> FUN</a><span class="demo-caption">CREATIVE ARCHIVE / 2026</span><button v-if="phase!=='home'" @click="skip">跳过开场 ↗</button><button v-else @click="replay">重播 ↺</button></header>
  <div class="intro-caption" :aria-hidden="phase==='home'"><span>IDEAS INTO PLAYABLE THINGS</span><p class="intro-title">每个想法，都有一个世界。</p></div>
  <div class="folder-position"><div class="folder-object">
   <div class="folder-shadow"></div><div class="folder-reveal-aura" aria-hidden="true"></div><div class="folder-back"><span>THE COLLECTION</span></div>
   <div class="inner-sheet"></div><div class="archive-glow" aria-hidden="true"></div>
   <div class="archive-cards" :class="{'archive-dragging':archiveDrag}" @pointerdown="startArchiveDrag" @pointerup="endArchiveDrag" @pointercancel="archiveDrag=null" @keydown.left.prevent="archiveTurn--" @keydown.right.prevent="archiveTurn++" aria-label="创作图片档案，可左右拖动浏览"><button type="button" v-for="(card,i) in visibleDeck" :key="card.src" class="archive-card" :style="{'--x':(i-(deck.length-1)/2)*9+'%','--r':(i-(deck.length-1)/2)*2.8+'deg','--i':i}" :inert="phase!=='home'" :aria-label="card.title+'，可拖动浏览'"><img :src="card.src" :alt="card.title" draggable="false"><span>{{card.title}}</span></button></div>
   <div class="folder-front"><span class="glass-sheen"></span><span class="folder-label"><img class="folder-wordmark" src="/images/branding/build-fun-wordmark.png" alt="Build Fun"><small>CREATIVE ARCHIVE / 杨缘馨</small></span><span class="folder-star">✧</span><span class="folder-count">{{String(cards.length).padStart(2,'0')}} FRAMES / {{deck.length}} WORLDS</span></div>
  </div></div>
  
  <section id="about" class="landing-copy" :inert="phase!=='home'"><HeroProfile v-if="phase==='home'" /></section>
  <footer v-if="!embedded"><span>AI CODING · GAME PROTOTYPING · CREATIVE DEVELOPMENT</span><a href="/">返回当前网站 ↗</a></footer>
 </section>
</template>
